    case_id, case_type, status, purpose,
    valid_from, valid_to, recorded_at, created_by
) VALUES (
    #{caseId}, #{caseType}, #{status}, #{purpose},
    #{validFrom, typeHandler=com.gien.gits.adapter.persistence.common.typehandler.InstantTypeHandler},
    #{validTo, typeHandler=com.gien.gits.adapter.persistence.common.typehandler.InstantTypeHandler},
    #{recordedAt, typeHandler=com.gien.gits.adapter.persistence.common.typehandler.InstantTypeHandler},
    #{createdBy}
)

mapper.select:
SELECT case_id, case_type, status, purpose,
       valid_from, valid_to, recorded_at, created_by
FROM operating_case WHERE case_id = #{caseId}
